(()=>{const reduce=matchMedia('(prefers-reduced-motion:reduce)').matches,b=document.body,s=document.createElement('style');s.textContent=`body{background:linear-gradient(135deg,#e7dbc8,#f8efdc 45%,#d7e5d8 100%);color:#2c302d}body:before{content:'';position:fixed;inset:0;pointer-events:none;z-index:-2;opacity:.42;background:repeating-linear-gradient(0deg,#00000005 0 1px,transparent 1px 5px),radial-gradient(circle at 20% 20%,#fff9 0 1px,transparent 2px)}.fxbar{position:fixed;top:0;left:0;width:100%;height:2px;background:#0001;z-index:100}.fxbar i{display:block;height:100%;width:0;background:#7fa58d;box-shadow:0 0 12px #7fa58d}.fx-sticker{position:fixed;pointer-events:none;z-index:3;opacity:0;font-family:cursive;font-weight:700;animation:sticker 10s ease-in-out infinite}.fx-confetti{position:fixed;pointer-events:none;z-index:3;width:9px;height:5px;border-radius:2px;opacity:0;animation:confetti 7s linear infinite}.fxr{opacity:0;transform:translateY(35px) rotate(.4deg);transition:1s cubic-bezier(.2,.8,.2,1)}.fxr.on{opacity:1;transform:none}.photo-card.selected{z-index:20;box-shadow:0 30px 80px #0006}.renewed:after{content:'🤝';position:fixed;inset:0;display:grid;place-items:center;z-index:80;pointer-events:none;font-size:120px;animation:stamp .9s ease both}@keyframes sticker{0%{transform:translate3d(0,18vh,0) rotate(-15deg) scale(.7);opacity:0}18%{opacity:.75}50%{transform:translate3d(35px,-8vh,0) rotate(12deg) scale(1)}100%{transform:translate3d(-30px,-35vh,0) rotate(30deg) scale(.8);opacity:0}}@keyframes confetti{0%{transform:translate3d(0,110vh,0) rotate(0);opacity:0}10%{opacity:.9}55%{transform:translate3d(45px,20vh,0) rotate(360deg)}100%{transform:translate3d(-50px,-25vh,0) rotate(720deg);opacity:0}}@keyframes stamp{0%{opacity:0;transform:scale(.4) rotate(-12deg)}55%{opacity:1;transform:scale(1.1) rotate(4deg)}100%{opacity:0;transform:scale(1)}}@media(prefers-reduced-motion:reduce){.fx-sticker,.fx-confetti{display:none}}`;b.appendChild(s);const bar=document.createElement('div');bar.className='fxbar';bar.innerHTML='<i></i>';b.appendChild(bar);if(!reduce){const stickers=['✦','★','♡','☻','LOL',':)','→','✎','☀','★','!!!','<3'];for(let i=0;i<26;i++){const x=document.createElement('span');x.className='fx-sticker';x.textContent=stickers[i%stickers.length];x.style.left=Math.random()*96+'%';x.style.top=25+Math.random()*70+'%';x.style.animationDelay=-Math.random()*10+'s';x.style.animationDuration=7+Math.random()*7+'s';x.style.fontSize=12+Math.random()*16+'px';b.appendChild(x)}for(let i=0;i<30;i++){const x=document.createElement('i');x.className='fx-confetti';x.style.left=Math.random()*100+'%';x.style.background=['#e98da3','#7fa58d','#e8bd69','#8aa8d0','#c7a0cf'][i%5];x.style.animationDelay=-Math.random()*7+'s';x.style.animationDuration=5+Math.random()*5+'s';b.appendChild(x)}}document.querySelectorAll('section').forEach(e=>e.classList.add('fxr'));const io=new IntersectionObserver(es=>es.forEach(e=>{if(e.isIntersecting){e.target.classList.add('on');io.unobserve(e.target)}}),{threshold:.1});document.querySelectorAll('.fxr').forEach(e=>io.observe(e));addEventListener('scroll',()=>{const m=document.documentElement.scrollHeight-innerHeight;bar.firstElementChild.style.width=(m?scrollY/m*100:0)+'%'})})();